-- Lernfeld 1 > Hardware > Auswahl und Komponenten > Peripheriegeräte > Monitore
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können Monitore unabhängig von den verfügbaren Videoanschlüssen ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "HDMI, DP oder VGA müssen kompatibel sein"}, {"text": "Ja", "correct": false, "because": "Inkompatibilität verhindert Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Auswahl von Monitoren immer die Anforderungen an die Bildschirmgröße berücksichtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Größe entscheidet über Nutzbarkeit"}, {"text": "Nein", "correct": false, "because": "Anforderungen sind entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Bildwiederholrate eines Monitors für Büroanwendungen irrelevant?', 2, '[{"text": "Ja", "correct": true, "because": "60 Hz reichen für einfache Aufgaben"}, {"text": "Nein", "correct": false, "because": "Meist ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Monitore ohne Rücksicht auf die Auflösung ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Auflösung beeinflusst Bildqualität"}, {"text": "Ja", "correct": false, "because": "Qualität ist relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Monitore mit höherer Bildwiederholrate immer teurer?', 2, '[{"text": "Ja", "correct": true, "because": "Höhere Rate erhöht Kosten"}, {"text": "Nein", "correct": false, "because": "Preisunterschied ist üblich"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor ist bei der Auswahl eines Monitors am wichtigsten?', 3, '[{"text": "Nutzungsanforderungen", "correct": true, "because": "Bestimmen Größe und Auflösung"}, {"text": "Marke", "correct": false, "because": "Sekundär"}, {"text": "Design", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Anschluss ist für moderne Monitore am häufigsten?', 2, '[{"text": "HDMI", "correct": true, "because": "Weit verbreitet und vielseitig"}, {"text": "VGA", "correct": false, "because": "Veraltet"}, {"text": "DVI", "correct": false, "because": "Weniger gebräuchlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einheit misst die Bildwiederholrate eines Monitors?', 2, '[{"text": "Hz", "correct": true, "because": "Hertz gibt Aktualisierungen pro Sekunde an"}, {"text": "DPI", "correct": false, "because": "Auflösung"}, {"text": "GB", "correct": false, "because": "Speichergröße"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Auflösung ist für Grafikdesign optimal?', 3, '[{"text": "4K (3840x2160)", "correct": true, "because": "Hohe Detailgenauigkeit"}, {"text": "Full HD (1920x1080)", "correct": false, "because": "Ausreichend, aber weniger präzise"}, {"text": "HD (1280x720)", "correct": false, "because": "Zu niedrig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Vorteil von LED-Monitoren?', 2, '[{"text": "Geringerer Stromverbrauch", "correct": true, "because": "Effizienter als ältere Technologien"}, {"text": "Höhere Kosten", "correct": false, "because": "Kein Vorteil"}, {"text": "Schwereres Gewicht", "correct": false, "because": "Nicht zutreffend"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte beeinflussen die Auswahl eines Monitors?', 4, '[{"text": "Auflösung", "correct": true, "because": "Bestimmt Bildqualität"}, {"text": "Bildwiederholrate", "correct": true, "because": "Beeinflusst Flüssigkeit"}, {"text": "Anschlussmöglichkeiten", "correct": true, "because": "Muss zum System passen"}, {"text": "Gewicht des Monitors", "correct": false, "because": "Weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Monitor mit hoher Bildwiederholrate?', 3, '[{"text": "Flüssigere Bewegungen", "correct": true, "because": "Wichtig für Gaming"}, {"text": "Geringere Latenz", "correct": true, "because": "Schnellere Anzeige"}, {"text": "Bessere Darstellung", "correct": true, "because": "Weniger Ruckeln"}, {"text": "Geringere Kosten", "correct": false, "because": "Höherer Preis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Monitorauswahl auftreten?', 3, '[{"text": "Inkompatibilität mit Anschlüssen", "correct": true, "because": "Falscher Port"}, {"text": "Unzureichende Auflösung", "correct": true, "because": "Minderwertige Qualität"}, {"text": "Zu niedrige Bildwiederholrate", "correct": true, "because": "Ruckeln bei Bewegung"}, {"text": "Falsche Farbe", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale sind für Gaming-Monitore wichtig?', 4, '[{"text": "Hohe Bildwiederholrate", "correct": true, "because": "Flüssige Darstellung"}, {"text": "Niedrige Reaktionszeit", "correct": true, "because": "Schnelle Reaktion"}, {"text": "Hohe Auflösung", "correct": true, "because": "Detailgenauigkeit"}, {"text": "Leiser Betrieb", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anschlüsse sind für Monitore üblich?', 3, '[{"text": "HDMI", "correct": true, "because": "Standard für Video und Audio"}, {"text": "DisplayPort", "correct": true, "because": "Hohe Bandbreite"}, {"text": "VGA", "correct": true, "because": "Älterer Standard"}, {"text": "SATA", "correct": false, "because": "Für Speicher"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Monitore mit 144 Hz sind für Gaming geeignet. b) Auflösung wird in Hz gemessen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "144 Hz ja, Auflösung in Pixel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) HDMI unterstützt 4K-Auflösung. b) Bildwiederholrate ist für Büroarbeiten entscheidend.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "HDMI ja, Rate weniger relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) DisplayPort bietet höhere Bandbreite als VGA. b) Alle Monitore sind mit jedem Anschluss kompatibel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DP ja, Kompatibilität variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Hohe Auflösung verbessert die Bildqualität. b) Monitore benötigen keine Stromversorgung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auflösung ja, Strom nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) LED-Monitore sind energieeffizienter als LCDs. b) Bildschirmgröße ist für die Auflösung irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "LED ja, Größe beeinflusst Auflösung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

